const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.2/projects/%7Bproject_id%7D/bid_packages/%7Bbid_package_id%7D/bids/%7Bid%7D',
  headers: {
    Authorization: 'Bearer REPLACE_BEARER_TOKEN',
    'content-type': 'application/json'
  },
  body: {
    bid: {
      lump_sum_amount: 10000,
      bidder_comments: 'Test Bid Comment',
      bidder_inclusion: 'Include Concrete',
      bidder_exclusion: 'Exclude Plumbing',
      bid_status: 'not_invited',
      is_bidder_committed: true,
      submitted: true,
      show_bid_in_estimating: true,
      vendor_id: 75414,
      prostore_file_ids: [1751318, 1837467],
      recipient_ids: [1751318, 1837467],
      bid_items: [
        {
          id: 123124112,
          bid_form_item_id: 32780682,
          cost_code_id: 32780682,
          amount: 100000,
          unit_cost: 900,
          quantity: 15,
          uom: 'pounds'
        }
      ],
      bid_items_to_delete: [1234324, 4992392]
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.2/projects/%7Bproject_id%7D/bid_packages/%7Bbid_package_id%7D/bids/%7Bid%7D"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
    Content = new StringContent("{\"bid\":{\"lump_sum_amount\":10000,\"bidder_comments\":\"Test Bid Comment\",\"bidder_inclusion\":\"Include Concrete\",\"bidder_exclusion\":\"Exclude Plumbing\",\"bid_status\":\"not_invited\",\"is_bidder_committed\":true,\"submitted\":true,\"show_bid_in_estimating\":true,\"vendor_id\":75414,\"prostore_file_ids\":[1751318,1837467],\"recipient_ids\":[1751318,1837467],\"bid_items\":[{\"id\":123124112,\"bid_form_item_id\":32780682,\"cost_code_id\":32780682,\"amount\":100000,\"unit_cost\":900,\"quantity\":15,\"uom\":\"pounds\"}],\"bid_items_to_delete\":[1234324,4992392]}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
